using System.Reflection;
using RoguePrince.CheatMenu;
using RoguePrince.CheatMenu.Core;
using UnityEngine;
int passed=0,failed=0;
void Assert(bool value){if(!value)throw new Exception("assertion failed");}
void Check(string name,Action work){try{work();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+(e.InnerException??e).Message);}}
const BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
var type=typeof(GameSession).Assembly.GetType("RoguePrince.CheatMenu.PlayerCheckpointActions");
Check("production player checkpoint adapter exists",()=>Assert(type!=null));
if(type==null){Console.WriteLine($"RESULT {passed} passed, {failed} failed");return 1;}
GameSession game=null;object actions=null;
object Call(string name,params object[] args)=>type.GetMethod(name,flags).Invoke(actions,args);
T Read<T>(string name)=>(T)type.GetProperty(name,flags).GetValue(actions);
void Reject(Action work){bool rejected=false;try{work();}catch{rejected=true;}Assert(rejected);}
void Setup(){game=new();actions=Activator.CreateInstance(type,flags,null,new object[]{game},null);Application.isFocused=true;Time.timeScale=1;TrainingActions.Scope=new(1,game.PlayerPointer.ToInt64(),3,4,0,0);TrainingActions.Validate=null;TeleportExtensions.Calls=0;TeleportExtensions.During=null;Plugin.Events.Clear();}
void Capture()=>Call("Capture");
void Move(){game.Player.transform.position=new(14,5,0);game.Health.currentHealth=20;game.Energy.energyCurrentValueStat=2;}
void Restore(Action release=null)=>Call("Restore",release??(Action)(()=>{}));
void Exact(float hp,int energy,float x)=>Assert(game.Health.currentHealth==hp&&game.Energy.energyCurrentValueStat==energy&&game.Player.transform.position==new Vector3(x,5,0));
Check("capture does not mutate native player",()=>{Setup();Capture();Exact(80,7,10);Assert(Read<bool>("HasCheckpoint")&&TeleportExtensions.Calls==0&&game.Energy.Writes==0);});
Check("restore applies recorded position health and energy without change triggers",()=>{Setup();Capture();Move();Restore();Exact(80,7,10);Assert(game.Energy.Triggers==0&&Read<bool>("HasCheckpoint")&&!Read<bool>("RecoveryPending"));});
Check("checkpoint can be restored repeatedly",()=>{Setup();Capture();for(int i=0;i<3;i++){Move();Restore();Exact(80,7,10);}Assert(TeleportExtensions.Calls==3);});
Check("recapture replaces previous values",()=>{Setup();Capture();Move();Capture();game.Health.currentHealth=60;Restore();Exact(20,2,14);});
Check("zero energy is a valid checkpoint",()=>{Setup();game.Energy.energyCurrentValueStat=0;Capture();game.Energy.energyCurrentValueStat=4;Restore();Exact(80,0,10);});
Check("restore without checkpoint never releases menu or writes",()=>{Setup();Reject(()=>Restore(()=>throw new Exception("released")));Assert(TeleportExtensions.Calls==0);});
foreach(var invalid in new[]{"nanHp","zeroHp","overHp","nanMax","zeroMax","negativeEnergy","overEnergy","zeroEnergyMax","uninitialized","airborne","paused","focus","busy","unsafe"})
 Check("invalid capture preserves absence: "+invalid,()=>{Setup();switch(invalid){case "nanHp":game.Health.currentHealth=float.NaN;break;case "zeroHp":game.Health.currentHealth=0;break;case "overHp":game.Health.currentHealth=101;break;case "nanMax":game.Health.maxHealth=float.NaN;break;case "zeroMax":game.Health.maxHealth=0;break;case "negativeEnergy":game.Energy.energyCurrentValueStat=-1;break;case "overEnergy":game.Energy.energyCurrentValueStat=11;break;case "zeroEnergyMax":game.Energy.energyMaxValueStat=0;break;case "uninitialized":game.Energy.isInitialized=false;break;case "airborne":game.Player.Platform.currentPlatform.Valid=false;break;case "paused":game.Player.context.Paused=true;break;case "focus":Application.isFocused=false;break;case "busy":type.GetField("CanMutate",flags).SetValue(actions,(Func<bool>)(()=>false));break;case "unsafe":TrainingActions.Validate=_=>throw new Exception("unsafe");break;}Reject(Capture);Assert(!Read<bool>("HasCheckpoint")&&TeleportExtensions.Calls==0);});
foreach(var change in new[]{"room","scene","generation","player","health","energy","context","hpMax","energyMax","dead","dying","focus","loading"})
 Check("checkpoint invalidates without native writes: "+change,()=>{Setup();Capture();Move();switch(change){case "room":TrainingActions.Scope=TrainingActions.Scope with {Room=5};break;case "scene":TrainingActions.Scope=TrainingActions.Scope with {Scene=4};break;case "generation":TrainingActions.Scope=TrainingActions.Scope with {Generation=2};break;case "player":game.Player=new();break;case "health":game.Player.Health=new();break;case "energy":game.Player.Energy=new();break;case "context":game.Player.context=new();break;case "hpMax":game.Health.maxHealth=120;break;case "energyMax":game.Energy.energyMaxValueStat=12;break;case "dead":game.Health.isAlive=false;break;case "dying":game.Health.onDieActionStarted=true;break;case "focus":Application.isFocused=false;break;}Call("Observe",change=="loading");Assert(!Read<bool>("HasCheckpoint")&&TeleportExtensions.Calls==0);});
foreach(var change in new[]{"room","caps","position","health","pause","time","busy"})
 Check("release-time changes reject before first write: "+change,()=>{Setup();Capture();Move();Reject(()=>Restore(()=>{switch(change){case "room":TrainingActions.Scope=TrainingActions.Scope with {Room=5};break;case "caps":game.Health.maxHealth=120;break;case "position":game.Player.transform.position=new(15,5,0);break;case "health":game.Health.currentHealth=21;break;case "pause":game.Player.context.Paused=true;break;case "time":Time.timeScale=0;break;case "busy":type.GetField("CanMutate",flags).SetValue(actions,(Func<bool>)(()=>false));break;}}));Assert(TeleportExtensions.Calls==0&&!Read<bool>("RecoveryPending"));});
Check("blocked target rejects before menu release",()=>{Setup();Capture();Move();TrainingActions.Validate=p=>{if(p.x==10)throw new Exception("occupied target");};int releases=0;Reject(()=>Restore(()=>releases++));Exact(20,2,14);Assert(releases==0&&TeleportExtensions.Calls==0);});
Check("native teleport throw after effect rolls back request-time state",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{if(p.x==10)throw new Exception("after teleport");};Reject(()=>Restore());Exact(20,2,14);Assert(!Read<bool>("RecoveryPending"));});
Check("incorrect teleport readback rolls back without applying vitals",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{if(p.x==10)e.transform.position=new(12,5,0);};Reject(()=>Restore());Exact(20,2,14);Assert(!Read<bool>("RecoveryPending"));});
Check("visible position drift of 0.3 units is rejected and rolled back",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{if(p.x==10)e.transform.position=new(10.3f,5,0);};Reject(()=>Restore());Exact(20,2,14);});
Check("focus loss inside native teleport stops checkpoint vitals and restores source",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{if(p.x==10)Application.isFocused=false;};Reject(()=>Restore());Exact(20,2,14);Assert(!Read<bool>("HasCheckpoint"));});
Check("NaN teleport result cannot claim position success or apply vitals",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{if(p.x==10)e.transform.position=new(float.NaN,5,0);};Reject(()=>Restore());Exact(20,2,14);Assert(!Read<bool>("RecoveryPending"));});
Check("infinite teleport result cannot claim success",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{if(p.x==10)e.transform.position=new(float.PositiveInfinity,5,0);};Reject(()=>Restore());Exact(20,2,14);});
Check("energy failure after mutation restores request-time energy and position",()=>{Setup();Capture();Move();game.Energy.DuringSet=n=>{if(n==7)throw new Exception("after energy");};Reject(()=>Restore());Exact(20,2,14);Assert(!Read<bool>("RecoveryPending"));});
Check("health failure restores energy and position",()=>{Setup();Capture();Move();game.Health.BeforeWrite=n=>{if(n==80)throw new Exception("health write");};Reject(()=>Restore());Exact(20,2,14);Assert(!Read<bool>("RecoveryPending"));});
Check("failed rollback retains recovery and explicit retry restores original state",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>throw new Exception("teleport uncertain");Reject(()=>Restore());Assert(Read<bool>("RecoveryPending"));Reject(Capture);Reject(()=>Call("Clear"));TeleportExtensions.During=null;Call("RetryRecovery");Exact(20,2,14);Assert(!Read<bool>("RecoveryPending"));});
Check("scope change during teleport never writes vitals into replacement scene",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{TrainingActions.Scope=TrainingActions.Scope with {Room=99};};Reject(()=>Restore());Assert(game.Health.currentHealth==20&&game.Energy.energyCurrentValueStat==2&&TeleportExtensions.Calls==1&&!Read<bool>("RecoveryPending")&&!Read<bool>("HasCheckpoint"));});
Check("replacement component during energy callback receives no old health write",()=>{Setup();Capture();Move();var replacement=new Damageable(){currentHealth=55};game.Energy.DuringSet=n=>game.Player.Health=replacement;Reject(()=>Restore());Assert(replacement.currentHealth==55&&TeleportExtensions.Calls==1&&!Read<bool>("RecoveryPending"));});
Check("zero health during native callback is never revived by checkpoint",()=>{Setup();Capture();Move();game.Energy.DuringSet=n=>game.Health.currentHealth=0;Reject(()=>Restore());Assert(game.Health.currentHealth==0&&!Read<bool>("RecoveryPending"));});
Check("failed recovery is retired on owner departure without writing new owner",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>throw new Exception("uncertain");Reject(()=>Restore());var calls=TeleportExtensions.Calls;game.Player=new();Call("Observe",false);Assert(!Read<bool>("RecoveryPending")&&TeleportExtensions.Calls==calls);});
Check("focus cleanup restores pending prior state without requiring focus",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>throw new Exception("uncertain");Reject(()=>Restore());TeleportExtensions.During=null;Application.isFocused=false;Call("Reset",false);Exact(20,2,14);Assert(!Read<bool>("RecoveryPending")&&!Read<bool>("HasCheckpoint"));});
Check("native pause keeps recovery record until explicit retry",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>{game.Player.context.Paused=true;throw new Exception("pause");};Reject(()=>Restore());Assert(Read<bool>("RecoveryPending"));TeleportExtensions.During=null;game.Player.context.Paused=false;Call("RetryRecovery");Exact(20,2,14);});
Check("maximum change during native callback keeps safe recovery rather than changing maxima",()=>{Setup();Capture();Move();game.Energy.DuringSet=n=>game.Health.maxHealth=120;Reject(()=>Restore());Assert(game.Health.currentHealth==20&&game.Health.maxHealth==120&&Read<bool>("RecoveryPending"));game.Health.maxHealth=100;game.Energy.DuringSet=null;Call("RetryRecovery");Exact(20,2,14);});
Check("observe does not repeatedly dispatch failed recovery",()=>{Setup();Capture();Move();TeleportExtensions.During=(e,p)=>throw new Exception("uncertain");Reject(()=>Restore());var calls=TeleportExtensions.Calls;for(int i=0;i<5;i++)Call("Observe",false);Assert(TeleportExtensions.Calls==calls&&Read<bool>("RecoveryPending"));});
Check("clear and inactive observe need no native read",()=>{Setup();Call("Clear");game.Player=null;Call("Observe",false);Call("Reset",true);Assert(!Read<bool>("HasCheckpoint"));});
Check("success log includes original player and room identity",()=>{Setup();Capture();Move();Restore();Assert(Plugin.Events.Any(x=>x.Contains("player_checkpoint_restored")&&x.Contains("room=4")&&x.Contains("player="+game.PlayerPointer.ToInt64())));});
Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
